     1→const express = require('express');
     2→const bcrypt = require('bcryptjs');
     3→const crypto = require('crypto');
     4→const pool = require('../lib/db');
     5→const {
     6→  generateToken,
     7→  generateLongToken,
     8→  generateRefreshToken,
     9→  rotateRefreshToken,
    10→  revokeAllTokens,
    11→  authMiddleware
    12→} = require('../lib/auth');
    13→
    14→const router = express.Router();
    15→
    16→// ============= EMAIL/PASSWORD AUTH =============
    17→
    18→// Register
    19→router.post('/register', async (req, res) => {
    20→  try {
    21→    const { email, password, name, role = 'candidate', company_name } = req.body;
    22→
    23→    if (!email || !password) {
    24→      return res.status(400).json({ error: 'Email and password are required' });
    25→    }
    26→
    27→    // Check if user exists
    28→    const existing = await pool.query('SELECT id FROM users WHERE email = $1', [email]);
    29→    if (existing.rows.length > 0) {
    30→      return res.status(400).json({ error: 'Email already registered' });
    31→    }
    32→
    33→    // Hash password
    34→    const password_hash = await bcrypt.hash(password, 10);
    35→
    36→    // Create user
    37→    const result = await pool.query(
    38→      `INSERT INTO users (email, password_hash, name, role, company_name)
    39→       VALUES ($1, $2, $3, $4, $5)
    40→       RETURNING id, email, name, role, company_name, created_at`,
    41→      [email, password_hash, name, role, company_name]
    42→    );
    43→
    44→    const user = result.rows[0];
    45→    const accessToken = generateToken(user);
    46→    const { token: refreshToken } = await generateRefreshToken(user.id);
    47→
    48→    // Track signup completion
    49→    try {
    50→      await pool.query(
    51→        'INSERT INTO events (event_type, user_id, metadata) VALUES ($1, $2, $3)',
    52→        [`signup_complete_${role}`, user.id, JSON.stringify({ email: user.email, role: role })]
    53→      );
    54→    } catch (e) {
    55→      console.error('Failed to log signup event:', e);
    56→    }
    57→
    58→    res.json({
    59→      success: true,
    60→      user: { id: user.id, email: user.email, name: user.name, role: user.role },
    61→      token: accessToken,
    62→      accessToken,
    63→      refreshToken
    64→    });
    65→  } catch (err) {
    66→    console.error('Registration error:', err);
    67→
    68→    if (err.code === '23505') {
    69→      return res.status(400).json({ error: 'This email is already registered' });
    70→    }
    71→    if (err.code === '42703') {
    72→      return res.status(500).json({ error: 'Database schema error. Please try again in a few minutes.' });
    73→    }
    74→
    75→    res.status(500).json({ error: 'Registration failed. Please try again.' });
    76→  }
    77→});
    78→
    79→// Login
    80→router.post('/login', async (req, res) => {
    81→  try {
    82→    const { email, password } = req.body;
    83→
    84→    if (!email || !password) {
    85→      return res.status(400).json({ error: 'Email and password are required' });
    86→    }
    87→
    88→    const result = await pool.query('SELECT * FROM users WHERE email = $1', [email]);
    89→    if (result.rows.length === 0) {
    90→      return res.status(401).json({ error: 'Invalid credentials' });
    91→    }
    92→
    93→    const user = result.rows[0];
    94→
    95→    // Check if user has password (might be OAuth-only user)
    96→    if (!user.password_hash) {
    97→      return res.status(401).json({
    98→        error: 'This account uses social login. Please sign in with Google or LinkedIn.',
    99→        oauth_only: true
   100→      });
   101→    }
   102→
   103→    const validPassword = await bcrypt.compare(password, user.password_hash);
   104→    if (!validPassword) {
   105→      return res.status(401).json({ error: 'Invalid credentials' });
   106→    }
   107→
   108→    const accessToken = generateToken(user);
   109→    const { token: refreshToken } = await generateRefreshToken(user.id);
   110→    req.session.token = accessToken;
   111→
   112→    res.json({
   113→      success: true,
   114→      user: {
   115→        id: user.id,
   116→        email: user.email,
   117→        name: user.name,
   118→        role: user.role,
   119→        is_paid: user.is_paid
   120→      },
   121→      token: accessToken,
   122→      accessToken,
   123→      refreshToken
   124→    });
   125→  } catch (err) {
   126→    console.error('Login error:', err);
   127→    res.status(500).json({ error: 'Login failed' });
   128→  }
   129→});
   130→
   131→// Refresh token endpoint
   132→router.post('/refresh', async (req, res) => {
   133→  try {
   134→    const { refreshToken } = req.body;
   135→
   136→    if (!refreshToken) {
   137→      return res.status(400).json({ error: 'Refresh token required' });
   138→    }
   139→
   140→    const result = await rotateRefreshToken(refreshToken);
   141→
   142→    if (result.error) {
   143→      return res.status(401).json({ error: result.error });
   144→    }
   145→
   146→    res.json({
   147→      success: true,
   148→      accessToken: result.accessToken,
   149→      refreshToken: result.refreshToken,
   150→      user: result.user
   151→    });
   152→  } catch (err) {
   153→    console.error('Token refresh error:', err);
   154→    res.status(500).json({ error: 'Token refresh failed' });
   155→  }
   156→});
   157→
   158→// Get current user
   159→router.get('/me', authMiddleware, (req, res) => {
   160→  res.json({
   161→    user: {
   162→      id: req.user.id,
   163→      email: req.user.email,
   164→      name: req.user.name,
   165→      role: req.user.role,
   166→      company_id: req.user.company_id,
   167→      company_name: req.user.company_name,
   168→      is_paid: req.user.is_paid,
   169→      google_id: req.user.google_id,
   170→      linkedin_id: req.user.linkedin_id,
   171→      created_at: req.user.created_at
   172→    }
   173→  });
   174→});
   175→
   176→// Logout (revoke all tokens)
   177→router.post('/logout', authMiddleware, async (req, res) => {
   178→  try {
   179→    await revokeAllTokens(req.user.id);
   180→    req.session.destroy();
   181→    res.json({ success: true });
   182→  } catch (err) {
   183→    console.error('Logout error:', err);
   184→    req.session.destroy();
   185→    res.json({ success: true });
   186→  }
   187→});
   188→
   189→// Logout from all devices
   190→router.post('/logout-all', authMiddleware, async (req, res) => {
   191→  try {
   192→    await revokeAllTokens(req.user.id);
   193→    res.json({ success: true, message: 'Logged out from all devices' });
   194→  } catch (err) {
   195→    console.error('Logout all error:', err);
   196→    res.status(500).json({ error: 'Failed to logout from all devices' });
   197→  }
   198→});
   199→
   200→// ============= OAUTH: GOOGLE =============
   201→
   202→// Get Google OAuth URL
   203→router.get('/google/url', (req, res) => {
   204→  const clientId = process.env.GOOGLE_CLIENT_ID;
   205→  const redirectUri = process.env.GOOGLE_REDIRECT_URI || `${req.protocol}://${req.get('host')}/api/auth/google/callback`;
   206→
   207→  if (!clientId) {
   208→    return res.status(503).json({
   209→      error: 'Google OAuth not configured',
   210→      configured: false
   211→    });
   212→  }
   213→
   214→  const scope = encodeURIComponent('openid email profile');
   215→  const state = crypto.randomBytes(16).toString('hex');
   216→
   217→  // Store state in session for validation
   218→  req.session.oauth_state = state;
   219→
   220→  const url = `https://accounts.google.com/o/oauth2/v2/auth?` +
   221→    `client_id=${clientId}` +
   222→    `&redirect_uri=${encodeURIComponent(redirectUri)}` +
   223→    `&response_type=code` +
   224→    `&scope=${scope}` +
   225→    `&state=${state}` +
   226→    `&access_type=offline` +
   227→    `&prompt=consent`;
   228→
   229→  res.json({ url, configured: true });
   230→});
   231→
   232→// Google OAuth callback
   233→router.get('/google/callback', async (req, res) => {
   234→  try {
   235→    const { code, state, error } = req.query;
   236→
   237→    if (error) {
   238→      return res.redirect(`/login.html?error=${encodeURIComponent(error)}`);
   239→    }
   240→
   241→    if (!code) {
   242→      return res.redirect('/login.html?error=No authorization code received');
   243→    }
   244→
   245→    // Exchange code for tokens
   246→    const tokenResponse = await fetch('https://oauth2.googleapis.com/token', {
   247→      method: 'POST',
   248→      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
   249→      body: new URLSearchParams({
   250→        client_id: process.env.GOOGLE_CLIENT_ID,
   251→        client_secret: process.env.GOOGLE_CLIENT_SECRET,
   252→        code,
   253→        grant_type: 'authorization_code',
   254→        redirect_uri: process.env.GOOGLE_REDIRECT_URI || `${req.protocol}://${req.get('host')}/api/auth/google/callback`
   255→      })
   256→    });
   257→
   258→    const tokens = await tokenResponse.json();
   259→
   260→    if (tokens.error) {
   261→      console.error('Google token error:', tokens);
   262→      return res.redirect('/login.html?error=Failed to authenticate with Google');
   263→    }
   264→
   265→    // Get user info
