   620→    const assessmentId = req.params.id;
   621→
   622→    // Get the assessment
   623→    const assessment = await pool.query(
   624→      'SELECT * FROM skill_assessments WHERE id = $1 AND user_id = $2',
   625→      [assessmentId, req.user.id]
   626→    );
   627→
   628→    if (assessment.rows.length === 0) {
   629→      return res.status(404).json({ error: 'Assessment not found' });
   630→    }
   631→
   632→    const questions = assessment.rows[0].questions;
   633→
   634→    // Get skill name for evaluation
   635→    let skillName = assessment.rows[0].title.replace(' Assessment', '');
   636→    if (assessment.rows[0].skill_id) {
   637→      const skill = await pool.query('SELECT skill_name FROM candidate_skills WHERE id = $1', [assessment.rows[0].skill_id]);
   638→      if (skill.rows.length > 0) skillName = skill.rows[0].skill_name;
