      'SELECT * FROM interviews WHERE id = $1 AND user_id = $2',
      [interview_id, req.user.id]
    );

    if (interview.rows.length === 0) {
      return res.status(404).json({ error: 'Interview not found' });
    }

    // Insert or update analysis
