   160→// Get company profile
   161→router.get('/profile', authMiddleware, async (req, res) => {
   162→  try {
   163→    if (!req.user.company_id) {
   164→      return res.status(400).json({ error: 'No company associated with this account' });
   165→    }
   166→
   167→    const result = await pool.query(
   168→      `SELECT c.*, ts.total_score as trust_score, ts.score_tier
   169→       FROM companies c
   170→       LEFT JOIN trust_scores ts ON c.id = ts.company_id
   171→       WHERE c.id = $1`,
   172→      [req.user.company_id]
   173→    );
   174→
   175→    if (result.rows.length === 0) {
   176→      return res.status(404).json({ error: 'Company not found' });
