   185→
   186→// Update company profile
   187→router.put('/profile', authMiddleware, async (req, res) => {
   188→  try {
   189→    if (!req.user.company_id) {
   190→      return res.status(400).json({ error: 'No company associated with this account' });
   191→    }
   192→
   193→    const {
   194→      name, description, industry, company_size, website,
   195→      linkedin_url, headquarters, founded_year, logo_url,
   196→      culture_description, core_values, benefits, office_locations
   197→    } = req.body;
   198→
   199→    // Calculate profile completeness
   200→    const fields = [
   201→      name, description, industry, company_size, website, logo_url, headquarters,
   202→      culture_description,
   203→      core_values && JSON.parse(core_values).length > 0,
   204→      benefits && JSON.parse(benefits).length > 0,
   205→      office_locations && JSON.parse(office_locations).length > 0
   206→    ];
   207→    const completedFields = fields.filter(f => f && (typeof f === 'boolean' ? f : f.length > 0)).length;
   208→    const completenessBonus = Math.round((completedFields / fields.length) * 30);
   209→
   210→    const result = await pool.query(
   211→      `UPDATE companies SET
   212→        name = COALESCE($1, name),
   213→        description = COALESCE($2, description),
   214→        industry = COALESCE($3, industry),
   215→        company_size = COALESCE($4, company_size),
   216→        website = COALESCE($5, website),
   217→        linkedin_url = COALESCE($6, linkedin_url),
   218→        headquarters = COALESCE($7, headquarters),
   219→        founded_year = COALESCE($8, founded_year),
   220→        logo_url = COALESCE($9, logo_url),
   221→        culture_description = COALESCE($10, culture_description),
   222→        core_values = COALESCE($11::jsonb, core_values),
   223→        benefits = COALESCE($12::jsonb, benefits),
   224→        office_locations = COALESCE($13::jsonb, office_locations),
   225→        updated_at = NOW()
   226→       WHERE id = $14
   227→       RETURNING *`,
   228→      [name, description, industry, company_size, website,
   229→       linkedin_url, headquarters, founded_year, logo_url,
   230→       culture_description, core_values, benefits, office_locations,
