   384→// Format date helper
   385→function formatDate(dateString) {
   386→  const date = new Date(dateString);
   387→  const now = new Date();
   388→  const diffMs = now - date;
   389→  const diffMins = Math.floor(diffMs / 60000);
   390→  const diffHours = Math.floor(diffMs / 3600000);
   391→  const diffDays = Math.floor(diffMs / 86400000);
   392→
   393→  if (diffMins < 1) return 'Just now';
   394→  if (diffMins < 60) return `${diffMins}m ago`;
   395→  if (diffHours < 24) return `${diffHours}h ago`;
   396→  if (diffDays < 7) return `${diffDays}d ago`;
   397→
   398→  return date.toLocaleDateString();
   399→}
