    13→// Auth check - uses checkAuth() from main.js which handles token properly
    14→async function initAuth() {
    15→  try {
    16→    // Use checkAuth from main.js which includes proper Authorization header
    17→    const user = await checkAuth();
    18→    if (!user) {
    19→      window.location.href = '/login.html';
    20→      return;
    21→    }
    22→    currentUser = user;
    23→
    24→    // Update UI
    25→    const userName = user.name || user.email?.split('@')[0] || 'User';
    26→    document.getElementById('user-name').textContent = userName;
    27→    document.getElementById('user-avatar').textContent = userName.charAt(0).toUpperCase();
    28→
    29→    // Check plan status
    30→    if (user.is_paid) {
    31→      document.getElementById('user-plan').textContent = 'Pro Plan';
    32→    }
    33→
    34→    // Load stats and documents
    35→    await Promise.all([
    36→      loadStats(),
    37→      loadDocuments()
    38→    ]);
    39→  } catch (error) {
    40→    console.error('Auth error:', error);
    41→    window.location.href = '/login.html';
    42→  }
    43→}
    44→
    45→// Load document stats - uses apiCall from main.js for proper auth
    46→async function loadStats() {
    47→  try {
    48→    const data = await apiCall('/documents/stats/summary');
    49→    if (!data) return;
    50→
    51→    const stats = data.stats;
    52→
    53→    document.getElementById('total-docs').textContent = stats.total_documents || 0;
    54→    document.getElementById('verified-docs').textContent = stats.verified_documents || 0;
    55→    document.getElementById('verified-credentials').textContent = stats.verified_credentials || 0;
    56→
    57→    const scoreBoost = stats.total_score_impact || 0;
    58→    document.getElementById('score-boost').textContent = scoreBoost > 0 ? `+${scoreBoost}` : scoreBoost;
    59→  } catch (error) {
    60→    console.error('Error loading stats:', error);
    61→  }
    62→}
    63→
    64→// Load all documents - uses apiCall from main.js for proper auth
    65→async function loadDocuments() {
    66→  try {
    67→    const data = await apiCall('/documents');
    68→    if (!data) return;
