   196→// Handle file upload
   197→async function handleFileUpload(file) {
   198→  if (!selectedDocType) {
   199→    alert('Please select a document type');
   200→    return;
   201→  }
   202→
   203→  // Validate file size (50MB)
   204→  if (file.size > 50 * 1024 * 1024) {
   205→    alert('File too large. Maximum size is 50MB.');
