   207→  }
   208→
   209→  // Show progress
   210→  const progressDiv = document.getElementById('upload-progress');
   211→  const progressFill = document.getElementById('progress-fill');
   212→  progressDiv.style.display = 'block';
   213→  progressFill.style.width = '10%';
   214→
   215→  try {
   216→    const formData = new FormData();
