   225→      method: 'POST',
   226→      headers: token ? { 'Authorization': `Bearer ${token}` } : {},
   227→      body: formData
   228→    });
   229→
   230→    progressFill.style.width = '80%';
   231→
   232→    if (!res.ok) {
   233→      const error = await res.json();
