   113→        daily_visitors: dailyVisitorsResult.rows,
   114→        date_range: { start: startDate, end: endDate }
   115→      }
   116→    });
   117→  } catch (error) {
   118→    console.error('Error fetching analytics:', error);
   119→    res.status(500).json({ error: 'Failed to fetch analytics data' });
