   235→    }
   236→
   237→    const result = await res.json();
   238→    progressFill.style.width = '100%';
   239→
   240→    // Success!
   241→    setTimeout(() => {
   242→      progressDiv.style.display = 'none';
   243→      progressFill.style.width = '0%';
   244→
   245→      // Clear selection
   246→      selectedDocType = null;
   247→      document.querySelectorAll('.doc-type-btn').forEach(b => b.classList.remove('selected'));
   248→
   249→      // Reload data
   250→      loadStats();
