    38→/**
    39→ * Upload and verify a document
    40→ * POST /api/documents/upload
    41→ */
    42→router.post('/upload', upload.single('document'), async (req, res) => {
    43→  try {
    44→    const { document_type } = req.body;
    45→    const userId = req.session?.user?.id || req.body.user_id;
    46→
    47→    if (!userId) {
    48→      return res.status(401).json({ error: 'Authentication required' });
    49→    }
    50→
    51→    if (!req.file) {
    52→      return res.status(400).json({ error: 'No file uploaded' });
    53→    }
    54→
    55→    if (!document_type) {
    56→      return res.status(400).json({ error: 'Document type required' });
    57→    }
    58→
    59→    const validTypes = ['resume', 'education_certificate', 'employment_letter', 'id_document', 'certification', 'reference_letter'];
    60→    if (!validTypes.includes(document_type)) {
    61→      return res.status(400).json({ error: 'Invalid document type' });
    62→    }
    63→
    64→    // Upload to R2
    65→    const formData = new FormData();
    66→    formData.append('file', req.file.buffer, {
    67→      filename: req.file.originalname,
    68→      contentType: req.file.mimetype
    69→    });
    70→
    71→    const uploadRes = await fetch('https://polsia.com/api/proxy/r2/upload', {
    72→      method: 'POST',
    73→      headers: {
    74→        'Authorization': `Bearer ${process.env.POLSIA_API_KEY}`,
    75→        ...formData.getHeaders()
    76→      },
    77→      body: formData
    78→    });
    79→
    80→    const uploadResult = await uploadRes.json();
    81→    if (!uploadResult.success) {
    82→      throw new Error(uploadResult.error?.message || 'File upload failed');
    83→    }
    84→
    85→    const fileUrl = uploadResult.file.url;
    86→
    87→    // Create document record
    88→    const result = await pool.query(`
    89→      INSERT INTO verification_documents (
    90→        user_id, document_type, original_filename, file_url,
    91→        file_size, mime_type, status
    92→      ) VALUES ($1, $2, $3, $4, $5, $6, 'pending')
    93→      RETURNING *
    94→    `, [
    95→      userId,
    96→      document_type,
    97→      req.file.originalname,
    98→      fileUrl,
    99→      req.file.size,
   100→      req.file.mimetype
   101→    ]);
   102→
   103→    const document = result.rows[0];
   104→
   105→    // Start verification process asynchronously
   106→    verifyDocument(document.id, userId)
   107→      .then(async (verificationResult) => {
   108→        console.log(`Document ${document.id} verified:`, verificationResult);
   109→
   110→        // Apply scores to OmniScore if verification passed
   111→        if (verificationResult.fraud_risk !== 'high') {
   112→          await applyDocumentScoresToOmniScore(userId);
   113→        }
   114→      })
   115→      .catch(error => {
   116→        console.error(`Verification failed for document ${document.id}:`, error);
   117→      });
   118→
   119→    res.json({
   120→      success: true,
   121→      document: {
   122→        id: document.id,
   123→        document_type: document.document_type,
   124→        filename: document.original_filename,
   125→        file_url: document.file_url,
   126→        status: document.status,
   127→        uploaded_at: document.uploaded_at
   128→      },
   129→      message: 'Document uploaded successfully. Verification in progress.'
   130→    });
   131→
   132→  } catch (error) {
   133→    console.error('Document upload error:', error);
   134→    res.status(500).json({
   135→      error: 'Failed to upload document',
   136→      message: error.message
   137→    });
   138→  }
