    82→      FROM events
    83→      WHERE event_type LIKE 'page_view%'
    84→        AND created_at >= $1
    85→        AND created_at <= $2
    86→      GROUP BY DATE(created_at)
    87→      ORDER BY date ASC
    88→    `, [startDate, endDate]);
    89→
    90→    // Conversion rates
