    50→        job_title: jobTitle,
    51→        job_description: jobDescription,
    52→        question_count: parseInt(questionCount)
    53→      })
    54→    });
    55→    
    56→    if (!data || !data.success) {
    57→      throw new Error(data?.error || 'Failed to start interview');
    58→    }
    59→    
    60→    interviewState.interviewId = data.interview.id;
    61→    interviewState.questions = data.questions;
    62→    interviewState.currentQuestionIndex = 0;
