   558→               COUNT(*) OVER () as total
   559→        FROM practice_sessions
   560→        WHERE user_id = $1
   561→      )
   562→      SELECT
   563→        AVG(CASE WHEN rn <= total/2 THEN score END) as first_half_avg,
   564→        AVG(CASE WHEN rn > total/2 THEN score END) as second_half_avg
   565→      FROM ordered_sessions`,
   566→      [req.user.id]
