   442→    res.redirect('/login.html?error=Authentication failed');
   443→  }
   444→});
   445→
   446→// ============= OAUTH STATUS =============
   447→
   448→// Get OAuth configuration status
   449→router.get('/oauth/status', (req, res) => {
   450→  res.json({
   451→    google: {
   452→      configured: !!process.env.GOOGLE_CLIENT_ID,
   453→      name: 'Google'
   454→    },
   455→    linkedin: {
   456→      configured: !!process.env.LINKEDIN_CLIENT_ID,
   457→      name: 'LinkedIn'
   458→    }
   459→  });
   460→});
   461→
   462→// Get connected OAuth providers for current user
   463→router.get('/oauth/connections', authMiddleware, async (req, res) => {
   464→  try {
   465→    const connections = await pool.query(
   466→      'SELECT provider, created_at FROM oauth_connections WHERE user_id = $1',
   467→      [req.user.id]
   468→    );
   469→
   470→    res.json({
   471→      success: true,
   472→      connections: connections.rows,
   473→      has_password: !!req.user.password_hash
   474→    });
   475→  } catch (err) {
   476→    console.error('Get OAuth connections error:', err);
   477→    res.status(500).json({ error: 'Failed to get OAuth connections' });
   478→  }
   479→});
   480→
   481→// ============= PAYMENT =============
   482→
   483→// Payment verification
   484→router.get('/verify-payment', authMiddleware, async (req, res) => {
   485→  try {
   486→    const sessionId = req.query.session_id;
   487→    if (!sessionId) {
   488→      return res.status(400).json({ error: 'Session ID required' });
   489→    }
   490→
   491→    // Verify with Polsia
   492→    const response = await fetch(
   493→      `${process.env.POLSIA_API_URL || 'https://polsia.com/api/proxy/ai'}/api/company-payments/verify?session_id=${sessionId}`,
   494→      { headers: { 'Authorization': `Bearer ${process.env.POLSIA_API_KEY}` } }
   495→    );
   496→    const { verified, payment } = await response.json();
   497→
   498→    if (verified) {
   499→      await pool.query(
   500→        'UPDATE users SET is_paid = true, stripe_subscription_id = $1 WHERE id = $2',
   501→        [payment.subscription_id || sessionId, req.user.id]
   502→      );
   503→      res.json({ success: true, verified: true });
   504→    } else {
   505→      res.json({ success: false, verified: false });
   506→    }
   507→  } catch (err) {
   508→    console.error('Payment verification error:', err);
   509→    res.status(500).json({ error: 'Verification failed' });
   510→  }
   511→});
