    if (!hasAccess) {
      return res.status(403).json({ error: 'Access denied' });
    }

    // Log access if accessed by someone other than owner
    if (userId !== document.user_id) {
      await logDocumentAccess(
        document.id,
        userId,
        'view',
        userCompanyId,
        req.ip
